const fs=require('fs');
const html=fs.readFileSync('/app/index.html','utf8');
if(/https?:\/\/|src=|href=|<img|<link/i.test(html)) throw new Error('external asset found');
const js=html.match(/<script>([\s\S]*)<\/script>/)[1];
const grad={addColorStop(){}};
const ctx=new Proxy({},{get:(o,k)=>{
  if(k==='createRadialGradient'||k==='createLinearGradient')return()=>grad;
  if(k==='canvas')return{};
  return typeof k==='string'?(()=>{}):undefined;
},set:()=>true});
let rafCb=null;
global.window={innerWidth:900,innerHeight:700,devicePixelRatio:1,matchMedia:()=>({matches:false}),addEventListener(){}};
global.document={getElementById:()=>({getContext:()=>ctx,width:0,height:0,style:{}})};
global.performance={now:()=>1000};
global.requestAnimationFrame=cb=>{rafCb=cb;};
eval(js);
if(!rafCb) throw new Error('no rAF queued');
rafCb(1016); rafCb(1033);
console.log('SMOKE OK frames rendered, external assets: none');
